css:
.gh-maintenance {
  --gh-green: #8fa78b;
  --gh-green-dark: #6f866c;
  --gh-green-pale: #e8eee5;
  --gh-cream: #faf8f1;
  --gh-cream-light: #fcfbf7;
  --gh-text: #555d59;
  --gh-line: #d8e0d4;
  color: var(--gh-text);
  font-family: "Zen Maru Gothic", "Hiragino Maru Gothic ProN", "Yu Gothic", Meiryo, sans-serif;
  font-size: 16px;
  line-height: 2;
  letter-spacing: 0.035em;
}

.gh-maintenance,
.gh-maintenance * {
  box-sizing: border-box;
}

.gh-maintenance .gh-inner {
  width: min(100%, 1080px);
  margin: 0 auto;
}

.gh-maintenance .gh-hero {
  margin-bottom: 56px;
  padding: 72px 32px;
  text-align: center;
  background: linear-gradient(135deg, var(--gh-cream-light), var(--gh-cream));
  border-top: 3px solid var(--gh-green);
  border-radius: 0 0 26px 26px;
}

.gh-maintenance .gh-eyebrow {
  margin: 0 0 12px;
  color: var(--gh-green-dark);
  font-size: 0.92rem;
  font-weight: 500;
  letter-spacing: 0.14em;
}

.gh-maintenance .gh-hero-title {
  margin: 0;
  color: var(--gh-text);
  font-size: clamp(1.8rem, 4vw, 2.65rem);
  font-weight: 500;
  line-height: 1.55;
}

.gh-maintenance .gh-hero-copy {
  max-width: 760px;
  margin: 24px auto 0;
  font-size: clamp(1rem, 2vw, 1.16rem);
}

.gh-maintenance .gh-section {
  margin: 0 0 64px;
}

.gh-maintenance .gh-lead,
.gh-maintenance .gh-message {
  max-width: 860px;
  margin: 0 auto;
  padding: 38px 44px;
  text-align: center;
  background: #fff;
  border: 1px solid var(--gh-line);
  border-radius: 20px;
}

.gh-maintenance .gh-heading {
  margin: 0 0 30px;
  padding-bottom: 13px;
  color: var(--gh-text);
  font-size: clamp(1.45rem, 3vw, 2rem);
  font-weight: 500;
  text-align: center;
  border-bottom: 1px solid var(--gh-line);
}

.gh-maintenance .gh-heading::after {
  display: block;
  width: 80px;
  height: 3px;
  margin: 13px auto -16px;
  background: var(--gh-green);
  content: "";
}

.gh-maintenance .gh-gentle-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px 22px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.gh-maintenance .gh-gentle-list li {
  position: relative;
  padding: 17px 18px 17px 48px;
  background: var(--gh-cream-light);
  border: 1px solid var(--gh-line);
  border-radius: 12px;
}

.gh-maintenance .gh-gentle-list li::before {
  position: absolute;
  top: 17px;
  left: 18px;
  color: var(--gh-green-dark);
  font-weight: 700;
  content: "○";
}

.gh-maintenance .gh-note-box {
  max-width: 900px;
  margin: 0 auto;
  padding: 38px 42px;
  background: var(--gh-cream);
  border-left: 4px solid var(--gh-green);
  border-radius: 4px 18px 18px 4px;
}

.gh-maintenance .gh-note-box p {
  margin: 0 0 20px;
}

.gh-maintenance .gh-note-box p:last-child {
  margin-bottom: 0;
}

.gh-maintenance .gh-emphasis {
  color: var(--gh-green-dark);
  font-size: clamp(1.12rem, 2vw, 1.32rem);
  font-weight: 500;
}

.gh-maintenance .gh-care-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 20px;
}

.gh-maintenance .gh-care-card {
  padding: 30px 24px;
  text-align: center;
  background: #fff;
  border: 1px solid var(--gh-line);
  border-radius: 18px;
}

.gh-maintenance .gh-care-mark {
  display: grid;
  width: 48px;
  height: 48px;
  margin: 0 auto 16px;
  color: #fff;
  font-size: 1.25rem;
  place-items: center;
  background: var(--gh-green);
  border-radius: 50%;
}

.gh-maintenance .gh-care-card h3 {
  margin: 0 0 10px;
  color: var(--gh-text);
  font-size: 1.08rem;
  font-weight: 500;
}

.gh-maintenance .gh-care-card p {
  margin: 0;
}

.gh-maintenance .gh-message {
  background: var(--gh-green-pale);
}

.gh-maintenance .gh-message p {
  margin: 0 0 18px;
}

.gh-maintenance .gh-message p:last-child {
  margin-bottom: 0;
}

.gh-maintenance .gh-details {
  overflow: hidden;
  margin: 0;
  background: #fff;
  border: 1px solid var(--gh-line);
  border-radius: 18px;
}

.gh-maintenance .gh-details-row {
  display: grid;
  grid-template-columns: 210px 1fr;
  border-bottom: 1px solid var(--gh-line);
}

.gh-maintenance .gh-details-row:last-child {
  border-bottom: 0;
}

.gh-maintenance .gh-details dt,
.gh-maintenance .gh-details dd {
  margin: 0;
  padding: 18px 22px;
}

.gh-maintenance .gh-details dt {
  font-weight: 500;
  background: var(--gh-green-pale);
}

.gh-maintenance .gh-price {
  color: var(--gh-green-dark);
  font-size: 1.2rem;
  font-weight: 700;
}

.gh-maintenance .gh-small-note {
  margin: 18px 0 0;
  font-size: 0.9rem;
}

.gh-maintenance .gh-closing {
  max-width: 900px;
  margin: 0 auto;
  padding: 46px 44px;
  text-align: center;
  background: var(--gh-cream);
  border-radius: 22px;
}

.gh-maintenance .gh-closing-title {
  margin: 0 0 18px;
  color: var(--gh-text);
  font-size: clamp(1.4rem, 3vw, 1.9rem);
  font-weight: 500;
}

.gh-maintenance .gh-closing p {
  margin: 0;
}

.gh-maintenance .gh-cta {
  padding: 54px 30px;
  text-align: center;
  background: var(--gh-green-pale);
  border-radius: 24px;
}

.gh-maintenance .gh-cta-title {
  margin: 0 0 12px;
  color: var(--gh-text);
  font-size: clamp(1.45rem, 3vw, 1.9rem);
  font-weight: 500;
}

.gh-maintenance .gh-cta p {
  margin: 0 0 24px;
}

.gh-maintenance .gh-button-row {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  justify-content: center;
}

.gh-maintenance .gh-button {
  display: inline-flex;
  min-width: 300px;
  min-height: 58px;
  padding: 12px 28px;
  align-items: center;
  justify-content: center;
  color: #fff !important;
  font-weight: 400;
  line-height: 1.5;
  text-align: center;
  text-decoration: none !important;
  background: var(--gh-green);
  border: 1px solid var(--gh-green);
  border-radius: 2px;
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.gh-maintenance .gh-button-secondary {
  color: var(--gh-green-dark) !important;
  background: #fff;
}

.gh-maintenance .gh-button:hover,
.gh-maintenance .gh-button:focus {
  opacity: 0.86;
  transform: translateY(-1px);
}

.gh-maintenance .gh-button-secondary:hover,
.gh-maintenance .gh-button-secondary:focus {
  color: var(--gh-green-dark) !important;
}

@media (max-width: 767px) {
  .gh-maintenance .gh-hero {
    margin-bottom: 40px;
    padding: 48px 20px;
  }

  .gh-maintenance .gh-section {
    margin-bottom: 48px;
  }

  .gh-maintenance .gh-lead,
  .gh-maintenance .gh-message,
  .gh-maintenance .gh-closing {
    padding: 28px 22px;
    text-align: left;
  }

  .gh-maintenance .gh-gentle-list,
  .gh-maintenance .gh-care-grid {
    grid-template-columns: 1fr;
  }

  .gh-maintenance .gh-note-box {
    padding: 28px 22px;
  }

  .gh-maintenance .gh-details-row {
    grid-template-columns: 1fr;
  }

  .gh-maintenance .gh-details dt {
    padding-bottom: 8px;
  }

  .gh-maintenance .gh-details dd {
    padding-top: 8px;
  }

  .gh-maintenance .gh-cta {
    padding: 38px 20px;
  }

  .gh-maintenance .gh-button-row {
    display: grid;
    grid-template-columns: 1fr;
  }

  .gh-maintenance .gh-button {
    width: 100%;
    min-width: 0;
  }
}
